<?php
declare(strict_types=1);

/*
 * How-to instructions for built-in exercises.
 * Source: free-exercise-db (https://github.com/yuhonas/free-exercise-db), public domain (Unlicense).
 * Keyed by exercise name. Exercises without an entry get a video-search link instead.
 */
return array (
  'Barbell Bench Press' => 
  array (
    0 => 'Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.',
    1 => 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.',
    2 => 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.',
    3 => 'Repeat the movement for the prescribed amount of repetitions.',
    4 => 'When you are done, place the bar back in the rack.',
  ),
  'Incline Barbell Bench Press' => 
  array (
    0 => 'Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.',
    1 => 'As you breathe in, come down slowly until you feel the bar on you upper chest.',
    2 => 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.',
    3 => 'Repeat the movement for the prescribed amount of repetitions.',
    4 => 'When you are done, place the bar back in the rack.',
  ),
  'Decline Bench Press' => 
  array (
    0 => 'Secure your legs at the end of the decline bench and slowly lay down on the bench.',
    1 => 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.',
    2 => 'As you breathe in, come down slowly until you feel the bar on your lower chest.',
    3 => 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).',
    4 => 'Repeat the movement for the prescribed amount of repetitions.',
    5 => 'When you are done, place the bar back in the rack.',
  ),
  'Dumbbell Bench Press' => 
  array (
    0 => 'Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.',
    1 => 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.',
    2 => 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.',
    3 => 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.',
    4 => 'Repeat the movement for the prescribed amount of repetitions of your training program.',
  ),
  'Incline Dumbbell Press' => 
  array (
    0 => 'Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.',
    1 => 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.',
    2 => 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.',
    3 => 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.',
    4 => 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.',
    5 => 'Repeat the movement for the prescribed amount of repetitions.',
    6 => 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.',
  ),
  'Dumbbell Fly' => 
  array (
    0 => 'Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.',
    1 => 'Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you\'re pressing them, but stop and hold just before you lock out. This will be your starting position.',
    2 => 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.',
    3 => 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.',
    4 => 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.',
  ),
  'Cable Crossover' => 
  array (
    0 => 'To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.',
    1 => 'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.',
    2 => 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.',
    3 => 'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.',
    4 => 'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.',
  ),
  'Machine Chest Press' => 
  array (
    0 => 'Sit down on the Chest Press Machine and select the weight.',
    1 => 'Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.',
    2 => 'Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.',
    3 => 'Now bring the handles back towards you as you breathe in.',
    4 => 'Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.',
    5 => 'Repeat for the recommended amount of reps.',
    6 => 'When finished step on the lever again and slowly get the handles back to their original place.',
  ),
  'Pec Deck' => 
  array (
    0 => 'Sit on the machine with your back flat on the pad.',
    1 => 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.',
    2 => 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.',
    3 => 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Push-Up' => 
  array (
    0 => 'Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.',
    1 => 'Next, lower yourself downward until your chest almost touches the floor as you inhale.',
    2 => 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.',
    3 => 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.',
  ),
  'Chest Dip' => 
  array (
    0 => 'For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.',
    1 => 'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.',
    2 => 'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.',
    3 => 'Repeat the movement for the prescribed amount of repetitions.',
  ),
  'Deadlift' => 
  array (
    0 => 'Stand in front of a loaded barbell.',
    1 => 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.',
    2 => 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.',
    3 => 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.',
    4 => 'Perform the amount of repetitions prescribed in the program.',
  ),
  'Barbell Row' => 
  array (
    0 => 'Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.',
    1 => 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.',
    2 => 'Then inhale and slowly lower the barbell back to the starting position.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Dumbbell Row' => 
  array (
    0 => 'Choose a flat bench and place a dumbbell on each side of it.',
    1 => 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.',
    2 => 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.',
    3 => 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.',
    4 => 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.',
    5 => 'Repeat the movement for the specified amount of repetitions.',
    6 => 'Switch sides and repeat again with the other arm.',
  ),
  'Lat Pulldown' => 
  array (
    0 => 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.',
    1 => 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.',
    2 => 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.',
    3 => 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.',
    4 => 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.',
    5 => 'Repeat this motion for the prescribed amount of repetitions.',
  ),
  'Close-Grip Lat Pulldown' => 
  array (
    0 => 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.',
    1 => 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.',
    2 => 'As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.',
    3 => 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.',
    4 => 'After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.',
    5 => '6. Repeat this motion for the prescribed amount of repetitions.',
  ),
  'Pull-Up' => 
  array (
    0 => 'Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.',
    1 => 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.',
    2 => 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.',
    3 => 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.',
    4 => 'Repeat this motion for the prescribed amount of repetitions.',
  ),
  'Chin-Up' => 
  array (
    0 => 'Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.',
    1 => 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.',
    2 => 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.',
    3 => 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.',
    4 => 'Repeat this motion for the prescribed amount of repetitions.',
  ),
  'Assisted Pull-Up' => 
  array (
    0 => 'Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.',
    1 => 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won\'t slip out. Take a medium to wide grip on the bar. This will be your starting position.',
    2 => 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.',
    3 => 'After a brief pause, return to the starting position.',
  ),
  'Face Pull' => 
  array (
    0 => 'Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.',
  ),
  'Straight-Arm Pulldown' => 
  array (
    0 => 'You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.',
    1 => 'Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.',
    2 => 'While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.',
    3 => 'While keeping the arms straight, go back to the starting position while breathing in.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Barbell Shrug' => 
  array (
    0 => 'Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.',
    1 => 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.',
    2 => 'Slowly return to the starting position as you breathe in.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Dumbbell Shrug' => 
  array (
    0 => 'Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.',
    1 => 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.',
    2 => 'Lower the dumbbells back to the original position.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Overhead Press' => 
  array (
    0 => 'Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.',
    1 => 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.',
    2 => 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.',
    3 => 'Lower the bar down to the collarbone slowly as you inhale.',
    4 => 'Lift the bar back up to the starting position as you exhale.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Seated Dumbbell Shoulder Press' => 
  array (
    0 => 'While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.',
    1 => 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.',
    2 => 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.',
    3 => 'Now, exhale and push the dumbbells upward until they touch at the top.',
    4 => 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Arnold Press' => 
  array (
    0 => 'Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.',
    1 => 'Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.',
    2 => 'Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.',
    3 => 'After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Machine Shoulder Press' => 
  array (
    0 => 'Sit down on the Shoulder Press Machine and select the weight.',
    1 => 'Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.',
    2 => 'Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.',
    3 => 'Lower the handles slowly back to the starting position as you inhale.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Dumbbell Lateral Raise' => 
  array (
    0 => 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.',
    1 => 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.',
    2 => 'Lower the dumbbells back down slowly to the starting position as you inhale.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Cable Lateral Raise' => 
  array (
    0 => 'Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.',
    1 => 'Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.',
    2 => 'Bend forward while keeping your back flat and rest your torso on the thighs.',
    3 => 'Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.',
    4 => 'While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.',
    5 => 'Slowly lower your arms to the starting position as you inhale.',
    6 => 'Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise.',
  ),
  'Dumbbell Front Raise' => 
  array (
    0 => 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.',
    1 => 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.',
    2 => 'Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.',
    3 => 'Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.',
  ),
  'Rear Delt Fly' => 
  array (
    0 => 'Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.',
    1 => 'While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.',
    2 => 'Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.',
    3 => 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.',
    4 => 'Repeat the recommended amount of repetitions.',
  ),
  'Upright Row' => 
  array (
    0 => 'Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.',
    1 => 'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.',
    2 => 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Barbell Curl' => 
  array (
    0 => 'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.',
    1 => 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.',
    2 => 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.',
    3 => 'Slowly begin to bring the bar back to starting position as your breathe in.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'EZ-Bar Curl' => 
  array (
    0 => 'Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.',
    1 => 'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.',
    2 => 'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.',
    3 => 'Then inhale and slowly lower the bar back to the starting position.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Dumbbell Curl' => 
  array (
    0 => 'Stand up straight with a dumbbell in each hand at arm\'s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.',
    1 => 'Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.',
    2 => 'Then, inhale and slowly begin to lower the dumbbells back to the starting position.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Hammer Curl' => 
  array (
    0 => 'Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.',
    1 => 'The palms of the hands should be facing your torso. This will be your starting position.',
    2 => 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.',
    3 => 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Incline Dumbbell Curl' => 
  array (
    0 => 'Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.',
    1 => 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.',
    2 => 'Slowly begin to bring the dumbbells back to starting position as your breathe in.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Preacher Curl' => 
  array (
    0 => 'To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.',
    1 => 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.',
    2 => 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.',
    3 => 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Cable Curl' => 
  array (
    0 => 'Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.',
    1 => 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.',
    2 => 'Slowly begin to bring the curl bar back to starting position as your breathe in.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Close-Grip Bench Press' => 
  array (
    0 => 'Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.',
    1 => 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.',
    2 => 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.',
    3 => 'Repeat the movement for the prescribed amount of repetitions.',
    4 => 'When you are done, place the bar back in the rack.',
  ),
  'Triceps Pushdown' => 
  array (
    0 => 'Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.',
    1 => 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.',
    2 => 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.',
    3 => 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Rope Triceps Pushdown' => 
  array (
    0 => 'Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).',
    1 => 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.',
    2 => 'Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.',
    3 => 'After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Skull Crusher' => 
  array (
    0 => 'Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.',
    1 => 'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.',
    2 => 'Lift the bar back to the starting position by extending the elbow and exhaling.',
    3 => 'Repeat.',
  ),
  'Overhead Triceps Extension' => 
  array (
    0 => 'To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.',
    1 => 'The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.',
    2 => 'Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.',
    3 => 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Dumbbell Kickback' => 
  array (
    0 => 'Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.',
    1 => 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.',
    2 => 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.',
    3 => 'Repeat the movement for the prescribed amount of repetitions.',
  ),
  'Triceps Dip' => 
  array (
    0 => 'To get into the starting position, hold your body at arm\'s length with your arms nearly locked above the bars.',
    1 => 'Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.',
    2 => 'Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.',
    3 => 'Repeat the movement for the prescribed amount of repetitions.',
  ),
  'Bench Dip' => 
  array (
    0 => 'For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.',
    1 => 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.',
    2 => 'Using your triceps to bring your torso up again, lift yourself back to the starting position.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Back Squat' => 
  array (
    0 => 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.',
    1 => 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.',
    2 => 'Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.',
    3 => 'Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.',
    4 => 'Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Front Squat' => 
  array (
    0 => 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.',
    1 => 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.',
    2 => 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).',
    3 => 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.',
    4 => 'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Goblet Squat' => 
  array (
    0 => 'Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.',
    1 => 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.',
    2 => 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.',
  ),
  'Smith Machine Squat' => 
  array (
    0 => 'To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.',
    1 => 'Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.',
    2 => 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).',
    3 => 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.',
    4 => 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Hack Squat' => 
  array (
    0 => 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.',
    1 => 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.',
    2 => 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).',
    3 => 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).',
    4 => 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.',
    5 => 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.',
    6 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Leg Press' => 
  array (
    0 => 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).',
    1 => 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.',
    2 => 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.',
    3 => 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.',
    4 => 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.',
  ),
  'Bulgarian Split Squat' => 
  array (
    0 => 'Position yourself into a staggered stance with the rear foot elevated and front foot forward.',
    1 => 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.',
    2 => 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.',
    3 => 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.',
  ),
  'Dumbbell Lunge' => 
  array (
    0 => 'Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.',
    1 => 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.',
    2 => 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.',
    3 => 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.',
  ),
  'Barbell Lunge' => 
  array (
    0 => 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.',
    1 => 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.',
    2 => 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>',
    3 => 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.',
    4 => 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.',
  ),
  'Walking Lunge' => 
  array (
    0 => 'Begin standing with your feet shoulder width apart and your hands on your hips.',
    1 => 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.',
    2 => 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.',
    3 => 'Step forward with your rear foot, repeating the lunge on the opposite leg.',
  ),
  'Step-Up' => 
  array (
    0 => 'Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).',
    1 => 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.',
    2 => 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.',
    3 => 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.',
  ),
  'Romanian Deadlift' => 
  array (
    0 => 'Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.',
    1 => 'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.',
    2 => 'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.',
    3 => 'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Stiff-Leg Deadlift' => 
  array (
    0 => 'Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.',
    1 => 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.',
    2 => 'Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.',
    3 => 'Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Sumo Deadlift' => 
  array (
    0 => 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.',
    1 => 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.',
    2 => 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.',
    3 => 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.',
  ),
  'Leg Extension' => 
  array (
    0 => 'For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.',
    1 => 'Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.',
    2 => 'Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.',
    3 => 'Repeat for the recommended amount of times.',
  ),
  'Lying Leg Curl' => 
  array (
    0 => 'Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.',
    1 => 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.',
    2 => 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.',
    3 => 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.',
  ),
  'Seated Leg Curl' => 
  array (
    0 => 'Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.',
    1 => 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.',
    2 => 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.',
    3 => 'Slowly return to the starting position as you breathe in.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Hip Thrust' => 
  array (
    0 => 'Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.',
    1 => 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.',
    2 => 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.',
  ),
  'Glute Bridge' => 
  array (
    0 => 'Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.',
    1 => 'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.',
    2 => 'Slowly go back to the starting position as you breathe in.',
  ),
  'Standing Calf Raise' => 
  array (
    0 => 'Adjust the padded lever of the calf raise machine to fit your height.',
    1 => 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.',
    2 => 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.',
    3 => 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Seated Calf Raise' => 
  array (
    0 => 'Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.',
    1 => 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.',
    2 => 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.',
    3 => 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.',
    4 => 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Bodyweight Squat' => 
  array (
    0 => 'Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.',
    1 => 'Begin the movement by flexing your knees and hips, sitting back with your hips.',
    2 => 'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.',
  ),
  'Crunch' => 
  array (
    0 => 'Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.',
    1 => 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don\'t lock your fingers behind your head.',
    2 => 'While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.',
    3 => 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don\'t cheat yourself by using momentum.',
    4 => 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Sit-Up' => 
  array (
    0 => 'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.',
    1 => 'Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.',
    2 => 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.',
    3 => 'Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Hanging Leg Raise' => 
  array (
    0 => 'Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.',
    1 => 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.',
    2 => 'Go back slowly to the starting position as you breathe in.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Cable Crunch' => 
  array (
    0 => 'Kneel below a high pulley that contains a rope attachment.',
    1 => 'Grasp cable rope attachment and lower the rope until your hands are placed next to your face.',
    2 => 'Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.',
    3 => 'With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.',
    4 => 'Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Russian Twist' => 
  array (
    0 => 'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.',
    1 => 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.',
    2 => 'Twist your torso to the right side until your arms are parallel with the floor while breathing out.',
    3 => 'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Plank' => 
  array (
    0 => 'Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.',
    1 => 'Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.',
  ),
  'Power Clean' => 
  array (
    0 => 'Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.',
    1 => 'Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.',
    2 => 'Place the bar about 1 inch in front of your shins and over the balls of your feet.',
    3 => 'Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.',
    4 => 'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.',
    5 => 'Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.',
    6 => 'Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.',
    7 => 'As the bar raises keep it as close to the shins as possible.',
    8 => 'As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.',
    9 => 'Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.',
  ),
  'Snatch' => 
  array (
    0 => 'Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.',
    1 => 'With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.',
    2 => 'Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.',
    3 => 'As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.',
    4 => 'Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.',
    5 => 'Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.',
    6 => 'Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead.',
  ),
  'Farmer\'s Carry' => 
  array (
    0 => 'There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren\'t available. Begin by standing between the implements.',
    1 => 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.',
    2 => 'Walk taking short, quick steps, and don\'t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.',
  ),
  'Running' => 
  array (
    0 => 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.',
    1 => 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.',
  ),
  'Walking' => 
  array (
    0 => 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.',
    1 => 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn\'t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.',
  ),
  'Cycling' => 
  array (
    0 => 'To begin, seat yourself on the bike and adjust the seat to your height.',
  ),
  'Smith Machine Bench Press' => 
  array (
    0 => 'Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.',
    1 => 'As you breathe in, come down slowly until you feel the bar on your middle chest.',
    2 => 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.',
    3 => 'Repeat the movement for the prescribed amount of repetitions.',
    4 => 'When you are done, lock the bar back in the rack.',
  ),
  'Svend Press' => 
  array (
    0 => 'Begin in a standing position.',
    1 => 'Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.',
    2 => 'Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.',
    3 => 'Pause at the top of the motion, and then slowly return to the starting position.',
  ),
  'Floor Press' => 
  array (
    0 => 'Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.',
    1 => 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.',
    2 => 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.',
  ),
  'Decline Push-Up' => 
  array (
    0 => 'Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.',
    1 => 'Next, lower yourself downward until your chest almost touches the floor as you inhale.',
    2 => 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.',
    3 => 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.',
  ),
  'Incline Push-Up' => 
  array (
    0 => 'Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.',
    1 => 'Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.',
    2 => 'Push body up until arms are extended. Repeat.',
  ),
  'Inverted Row' => 
  array (
    0 => 'Position a bar in a rack to about waist height. You can also use a smith machine.',
    1 => 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.',
    2 => 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.',
    3 => 'Pause at the top of the motion, and return yourself to the start position.',
    4 => 'Repeat for the desired number of repetitions.',
  ),
  'Wide-Grip Pull-Up' => 
  array (
    0 => 'Grab the pull-up bar with the palms facing forward using a wide grip.',
    1 => 'As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.',
    2 => 'Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.',
    3 => 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.',
    4 => 'Repeat this motion for the prescribed amount of repetitions.',
  ),
  'Muscle-Up' => 
  array (
    0 => 'Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.',
    1 => 'As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.',
    2 => 'Maintaining control and stability, extend through the elbow to complete the motion.',
    3 => 'Use care when lowering yourself to the ground.',
  ),
  'Good Morning' => 
  array (
    0 => 'Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.',
    1 => 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.',
    2 => 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.',
  ),
  'Reverse Hyperextension' => 
  array (
    0 => 'Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.',
    1 => 'To begin the movement, flex the hips, pulling the legs forward.',
    2 => 'Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.',
    3 => 'Return by again flexing the hip, pulling the carriage forward as far as you can.',
    4 => 'Repeat for the desired number of repetitions.',
  ),
  'Trap Bar Deadlift' => 
  array (
    0 => 'For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.',
    1 => 'Lower your hips, look forward with your head and keep your chest up.',
    2 => 'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.',
    3 => 'At the completion of the movement, lower the weight back to the ground under control.',
  ),
  'Deficit Deadlift' => 
  array (
    0 => 'Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.',
    1 => 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.',
    2 => 'Lower the bar by bending at the hips and guiding it to the floor.',
  ),
  'Dumbbell Deadlift' => 
  array (
    0 => 'Grasp a couple of dumbbells holding them by your side at arm\'s length.',
    1 => 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.',
    2 => 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement',
    3 => 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Superman' => 
  array (
    0 => 'To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.',
    1 => 'Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.',
    2 => 'Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.',
    3 => 'Repeat for the recommended amount of repetitions prescribed in your program.',
  ),
  'Cuban Press' => 
  array (
    0 => 'Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position.',
    1 => 'To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.',
    2 => 'Now press the dumbbells by extending at the elbows, straightening your arms overhead.',
    3 => 'Return to the starting position as you breathe in by reversing the steps.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Cable Rear Delt Fly' => 
  array (
    0 => 'Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.',
    1 => 'Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.',
    2 => 'Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.',
    3 => 'Pause at the end of the motion before returning the handles to the start position.',
  ),
  'Standing Dumbbell Shoulder Press' => 
  array (
    0 => 'While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.',
    1 => 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.',
    2 => 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.',
    3 => 'Now, exhale and push the dumbbells upward until they touch at the top.',
    4 => 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Zottman Curl' => 
  array (
    0 => 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.',
    1 => 'Make sure the palms of the hands are facing each other. This will be your starting position.',
    2 => 'While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.',
    3 => 'Hold the contracted position for a second as you squeeze the biceps.',
    4 => 'Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.',
    5 => 'Slowly begin to bring the dumbbells back down using the pronated grip.',
    6 => 'As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.',
    7 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Spider Curl' => 
  array (
    0 => 'Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.',
    1 => 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.',
    2 => 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.',
    3 => 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.',
    4 => 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.',
    5 => 'Slowly begin to bring the barbell back to the starting position as your breathe in. .',
    6 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Drag Curl' => 
  array (
    0 => 'Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.',
    1 => 'As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.',
    2 => 'Slowly go back to the starting position as you keep the bar in contact with the torso at all times.',
    3 => 'Repeat for the recommended amount of repetitions.',
  ),
  'JM Press' => 
  array (
    0 => 'Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.',
    1 => 'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.',
    2 => 'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.',
    3 => 'Now go back to the starting position and start over.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Reverse-Grip Triceps Pushdown' => 
  array (
    0 => 'Start by setting a bar attachment (straight or e-z) on a high pulley machine.',
    1 => 'Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.',
    2 => 'Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.',
    3 => 'Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Tate Press' => 
  array (
    0 => 'Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.',
    1 => 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.',
    2 => 'Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.',
    3 => 'As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.',
    4 => 'Repeat the movement for the prescribed amount of repetitions of your training program.',
  ),
  'Overhead Squat' => 
  array (
    0 => 'Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.',
    1 => 'Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.',
    2 => 'Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.',
    3 => 'Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.',
    4 => 'Now use your feet and legs to help bring the weight back up to the starting position while exhaling.',
    5 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Glute-Ham Raise' => 
  array (
    0 => 'Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.',
    1 => 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.',
    2 => 'Return to the starting position, keeping your descent under control.',
  ),
  'Barbell Glute Bridge' => 
  array (
    0 => 'Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.',
    1 => 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.',
    2 => 'Extend as far as possible, then reverse the motion to return to the starting position.',
  ),
  'Dead Bug' => 
  array (
    0 => 'Begin lying on your back with your hands extended above you toward the ceiling.',
    1 => 'Bring your feet, knees, and hips up to 90 degrees.',
    2 => 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.',
    3 => 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.',
    4 => 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.',
    5 => 'Stay tight and return the working leg to the starting position.',
    6 => 'Repeat on the opposite side, alternating until the set is complete.',
  ),
  'Flutter Kicks' => 
  array (
    0 => 'On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.',
    1 => 'Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.',
    2 => 'Start the movement by lifting the left leg higher than the right leg.',
    3 => 'Then lower the left leg as you lift the right leg.',
    4 => 'Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.',
  ),
  'Pallof Press' => 
  array (
    0 => 'Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.',
    1 => 'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm\'s length away from the pulley, with the tension of the weight on the cable.',
    2 => 'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.',
    3 => 'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.',
    4 => 'Hold the repetition for several seconds before returning to the starting position.',
    5 => 'At the conclusion of the set, repeat facing the other direction.',
  ),
  'Dumbbell Side Bend' => 
  array (
    0 => 'Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.',
    1 => 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.',
    2 => 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.',
    3 => 'Repeat for the recommended amount of repetitions and then change hands.',
  ),
  'Reverse Crunch' => 
  array (
    0 => 'Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.',
    1 => 'Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.',
    2 => 'While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.',
    3 => 'Hold the contraction for a second and move your legs back to the starting position while exhaling.',
    4 => 'Repeat for the recommended amount of repetitions.',
  ),
  'Clean and Jerk' => 
  array (
    0 => 'With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.',
    1 => 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.',
    2 => 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.',
    3 => 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.',
    4 => 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.',
    5 => 'The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.',
    6 => 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.',
    7 => 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.',
  ),
  'Hang Clean' => 
  array (
    0 => 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.',
    1 => 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.',
    2 => 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.',
  ),
  'Hang Snatch' => 
  array (
    0 => 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.',
    1 => 'Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.',
    2 => 'As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.',
    3 => 'Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control.',
  ),
  'Clean Pull' => 
  array (
    0 => 'With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.',
    1 => 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.',
    2 => 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.',
  ),
  'Tire Flip' => 
  array (
    0 => 'Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.',
    1 => 'To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.',
    2 => 'As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary.',
  ),
  'Sled Push' => 
  array (
    0 => 'Load your pushing sled with the desired weight.',
    1 => 'Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.',
  ),
  'Rope Climb' => 
  array (
    0 => 'Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.',
    1 => 'Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.',
    2 => 'Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.',
    3 => 'Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.',
    4 => 'To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion.',
  ),
  'Star Jump' => 
  array (
    0 => 'Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.',
    1 => 'To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.',
    2 => 'As you land, bring your limbs back in and absorb your impact through the legs.',
  ),
  'Jogging' => 
  array (
    0 => 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.',
    1 => 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.',
  ),
);
